#!/usr/bin/env node

// gfxstream's Vulkan wire format of src/graphics_adapters/virtio_gpu/
// gfxstream_protocol.js (generated by tools/gfxstream_protocol_gen.mjs from
// the guest's C) against the guest's own code: gfxstream_protocol_vectors.txt
// holds structs the guest's request writers wrote (tools/gfxstream_oracle),
// which must decode to what they were made of and encode again
// (tests/devices/gfxstream_guest_protocol.js) to the same bytes; and replies
// this encoder wrote, with what the guest's reply readers read of them
// (written again by the guest), which must still come out the same.
//
// With --oracle <tools/gfxstream_oracle's build>, it writes the vectors again.

import assert from "assert/strict";
import fs from "node:fs";
import url from "node:url";
import { execFileSync } from "node:child_process";

const __dirname = url.fileURLToPath(new URL(".", import.meta.url));
const P = await import("../../src/graphics_adapters/virtio_gpu/gfxstream_protocol.js");
const { GUEST_STRUCTS, GUEST_COMMANDS } = await import("./gfxstream_guest_protocol.js");
const VECTORS = __dirname + "/gfxstream_protocol_vectors.txt";

const unhex = hex => Uint8Array.from(hex.match(/../g) || [], h => parseInt(h, 16));
const hex = bytes => Array.from(bytes, b => b.toString(16).padStart(2, "0")).join("");
const ROOT_NONE = 0x7FFFFFFF;
// VkStructureType
const S = {
    PHYSICAL_DEVICE_VULKAN_1_1_PROPERTIES: 50, PHYSICAL_DEVICE_VULKAN_1_2_FEATURES: 51, PHYSICAL_DEVICE_FEATURES_2: 1000059000,
    PHYSICAL_DEVICE_PROPERTIES_2: 1000059001, IMAGE_FORMAT_PROPERTIES_2: 1000059003, EXTERNAL_IMAGE_FORMAT_PROPERTIES: 1000071001,
    MEMORY_DEDICATED_REQUIREMENTS: 1000127000, MEMORY_REQUIREMENTS_2: 1000146003, PHYSICAL_DEVICE_DRIVER_PROPERTIES: 1000196000,
};

// The replies: objects as the device's Vulkan model fills them
const REPLIES = {
    VkPhysicalDeviceProperties2: { sType: S.PHYSICAL_DEVICE_PROPERTIES_2,
        pNext: { sType: S.PHYSICAL_DEVICE_DRIVER_PROPERTIES, driverID: 10, driverName: "v64", driverInfo: "gfxstream on WebGPU",
            conformanceVersion: { major: 1, minor: 3, subminor: 0, patch: 0 },
            pNext: { sType: S.PHYSICAL_DEVICE_VULKAN_1_1_PROPERTIES, pNext: null, deviceUUID: Uint8Array.from({ length: 16 }, (_, i) => i + 1),
                driverUUID: new Uint8Array(16).fill(7), deviceLUID: new Uint8Array(8), deviceNodeMask: 1, deviceLUIDValid: 0, subgroupSize: 4,
                subgroupSupportedStages: 0x1F, subgroupSupportedOperations: 0xFF, subgroupQuadOperationsInAllStages: 1, pointClippingBehavior: 0,
                maxMultiviewViewCount: 6, maxMultiviewInstanceIndex: 1 << 27, protectedNoFault: 0, maxPerSetDescriptors: 1024,
                maxMemoryAllocationSize: 2 ** 31 } },
        properties: { apiVersion: 1 << 22 | 3 << 12, driverVersion: 1, vendorID: 0x1AE0, deviceID: 2, deviceType: 4, deviceName: "v64 WebGPU",
            pipelineCacheUUID: new Uint8Array(16).fill(0xAB),
            limits: { maxImageDimension2D: 8192, maxComputeWorkGroupCount: [65535, 65535, 65535], pointSizeRange: [1, 64],
                timestampPeriod: 1.5, nonCoherentAtomSize: 64, bufferImageGranularity: 1 },
            sparseProperties: {} } },
    VkPhysicalDeviceFeatures2: { sType: S.PHYSICAL_DEVICE_FEATURES_2, features: { robustBufferAccess: 1, samplerAnisotropy: 1 },
        pNext: { sType: S.PHYSICAL_DEVICE_VULKAN_1_2_FEATURES, pNext: null, timelineSemaphore: 1, bufferDeviceAddress: 0, vulkanMemoryModel: 1 } },
    VkPhysicalDeviceMemoryProperties: { memoryTypeCount: 2, memoryTypes: [{ propertyFlags: 1, heapIndex: 0 }, { propertyFlags: 7, heapIndex: 0 }],
        memoryHeapCount: 1, memoryHeaps: [{ size: 2 ** 32, flags: 1 }] },
    VkMemoryRequirements2: { sType: S.MEMORY_REQUIREMENTS_2, memoryRequirements: { size: 0x123000, alignment: 4096, memoryTypeBits: 3 },
        pNext: { sType: S.MEMORY_DEDICATED_REQUIREMENTS, pNext: null, prefersDedicatedAllocation: 1, requiresDedicatedAllocation: 0 } },
    VkQueueFamilyProperties: { queueFlags: 7, queueCount: 1, timestampValidBits: 64, minImageTransferGranularity: { width: 1, height: 1, depth: 1 } },
    VkExtensionProperties: { extensionName: "VK_KHR_swapchain", specVersion: 70 },
    VkFormatProperties: { linearTilingFeatures: 0x1, optimalTilingFeatures: 0x1D401, bufferFeatures: 0x58 },
    VkSubresourceLayout: { offset: 0, size: 640 * 480 * 4, rowPitch: 2560, arrayPitch: 0, depthPitch: 0 },
    VkImageFormatProperties2: { sType: S.IMAGE_FORMAT_PROPERTIES_2,
        imageFormatProperties: { maxExtent: { width: 8192, height: 8192, depth: 1 }, maxMipLevels: 14, maxArrayLayers: 256, sampleCounts: 5, maxResourceSize: 2 ** 31 },
        pNext: { sType: S.EXTERNAL_IMAGE_FORMAT_PROPERTIES, pNext: null,
            externalMemoryProperties: { externalMemoryFeatures: 3, exportFromImportedHandleTypes: 0x400, compatibleHandleTypes: 0x400 } } },
};
const reply_hex = name => {
    const w = new P.GfxWriter(16);
    P.STRUCTS[name][1](w, REPLIES[name], ROOT_NONE);
    return hex(w.result());
};

if(process.argv[2] === "--oracle")
{
    const oracle = process.argv[3];
    const lines = ["# tests/devices/gfxstream_protocol.js --oracle <tools/gfxstream_oracle's build> writes these",
        "# request: what the guest's reservedmarshal_* wrote; reply: this encoder's; guest: the reply as the guest read it, written again"];
    for(const line of execFileSync(oracle, ["requests"], { encoding: "utf8" }).trim().split("\n")) lines.push("request " + line);
    const replies = Object.keys(REPLIES).map(name => name + " " + reply_hex(name)).join("\n") + "\n";
    for(const line of replies.trim().split("\n")) lines.push("reply " + line);
    for(const line of execFileSync(oracle, ["replies"], { input: replies, encoding: "utf8" }).trim().split("\n")) lines.push("guest " + line);
    fs.writeFileSync(VECTORS, lines.join("\n") + "\n");
    console.log("wrote " + VECTORS);
    process.exit(0);
}

const vectors = { request: [], reply: {}, guest: {} };
for(const line of fs.readFileSync(VECTORS, "utf8").split("\n"))
{
    if(!line || line.startsWith("#")) continue;
    const [kind, name, data] = line.split(" ");
    if(kind === "request") vectors.request.push([name, data || ""]);
    else vectors[kind][name] = data || "";
}

/** a request's struct, decoded; the guest's pointers (addresses) as 1 */
const decode = (name, data) => {
    const bytes = unhex(data);
    const r = new P.GfxReader(bytes);
    r.presences = [];
    const o = P.STRUCTS[name][0](r, ROOT_NONE);
    assert.equal(r.p, bytes.length, name + ": all of it read");
    const normal = bytes.slice();
    for(const at of r.presences)
    {
        const set = normal.subarray(at, at + 8).some(b => b);
        normal.fill(0, at, at + 8);
        if(set) normal[at + 7] = 1;
    }
    return { o, normal };
};

// Every request decodes and encodes again to the guest's bytes
const decoded = {};
for(const [name, data] of vectors.request)
{
    const { o, normal } = decode(name, data);
    const w = new P.GfxWriter(16);
    GUEST_STRUCTS[name][0](w, o, ROOT_NONE);
    assert.equal(hex(w.result()), hex(normal), name + ": encoded again");
    (decoded[name] = decoded[name] || []).push(o);
}
console.log("PASS: " + vectors.request.length + " structs of the guest's request writers, decoded and encoded again");

// What they decode to
let o = decoded.VkInstanceCreateInfo[0];
assert.deepEqual(o.ppEnabledExtensionNames, ["VK_KHR_surface", "VK_EXT_debug_utils"]);
assert.equal(o.pApplicationInfo.pApplicationName, "vktest");
assert.equal(o.pApplicationInfo.pEngineName, null);
assert.equal(o.pApplicationInfo.apiVersion, 1 << 22 | 3 << 12);
o = decoded.VkDeviceCreateInfo[0];
assert.equal(o.pNext.sType, S.PHYSICAL_DEVICE_FEATURES_2);
assert.equal(o.pNext.features.samplerAnisotropy, 1);
assert.equal(o.pNext.pNext.shaderDrawParameters, 1, "Vulkan11Features in the chain");
assert.equal(o.pQueueCreateInfos[0].pQueuePriorities[0], 1);
assert.deepEqual(o.ppEnabledExtensionNames, ["VK_KHR_swapchain"]);
assert.equal(o.pEnabledFeatures, null);
o = decoded.VkImageCreateInfo[0];
assert.equal(o.pNext.handle, 77, "VkNativeBufferANDROID's handle: what it points to");
assert.deepEqual([o.pNext.stride, o.pNext.format, o.pNext.usage, o.pNext.usage2.consumer, o.pNext.usage2.producer], [640, 1, 0x300, 5, 6]);
assert.deepEqual([o.extent.width, o.extent.height, o.format, o.usage], [640, 480, 37, 0x17]);
assert.deepEqual(Array.from(o.pQueueFamilyIndices), [0, 1]);
o = decoded.VkMemoryAllocateInfo[0];
assert.equal(o.pNext.colorBuffer, 42, "VkImportColorBufferGOOGLE (the chain's root decides the sType)");
assert.equal(o.pNext.pNext.image, 0x55);
assert.deepEqual([o.allocationSize, o.memoryTypeIndex], [1 << 20, 3]);
o = decoded.VkGraphicsPipelineCreateInfo[0];
assert.equal(o.pStages[1].pName, "main");
assert.equal(o.pStages[1].pSpecializationInfo.dataSize, 4);
assert.deepEqual(Array.from(o.pStages[1].pSpecializationInfo.pData), [4, 3, 2, 1]);
assert.equal(o.pVertexInputState.pVertexAttributeDescriptions[1].offset, 8);
assert.equal(o.pTessellationState, null);
assert.equal(o.pViewportState.pViewports[0].width, 640);
assert.equal(o.pMultisampleState.pSampleMask[0], 0xFFFFFFFF);
assert.deepEqual(Array.from(o.pColorBlendState.blendConstants), [0.25, 0.5, 0.75, 1]);
assert.deepEqual(Array.from(o.pDynamicState.pDynamicStates), [0, 1]);
assert.deepEqual([o.layout, o.renderPass, o.basePipelineIndex], [0x60, 0x61, -1]);
const [sampler, uniform, texel] = decoded.VkWriteDescriptorSet;
assert.equal(sampler.pImageInfo[0].imageView, 0x72);
assert.deepEqual(sampler.pBufferInfo, [], "a buffer pointer of an image descriptor: there, its contents not");
assert.deepEqual(uniform.pBufferInfo.map(b => b.buffer), [0x73, 0x74]);
assert.equal(uniform.pBufferInfo[1].range, 2 ** 64, "VK_WHOLE_SIZE");
assert.deepEqual(texel.pTexelBufferView, [0x75]);
o = decoded.VkDescriptorSetLayoutCreateInfo[0];
assert.deepEqual(o.pBindings[0].pImmutableSamplers, [0x70]);
assert.equal(o.pBindings[1].pImmutableSamplers, null);
o = decoded.VkShaderModuleCreateInfo[0];
assert.equal(o.codeSize, 12);
assert.deepEqual(Array.from(o.pCode), [0x07230203, 0x00010000, 0x0008000a]);
o = decoded.VkSubmitInfo[0];
assert.deepEqual([o.pWaitSemaphores, Array.from(o.pWaitDstStageMask), o.pCommandBuffers, o.pSignalSemaphores], [[1], [0x400], [2, 3], [4]]);
assert.deepEqual([o.pNext.pWaitSemaphoreValues, o.pNext.pSignalSemaphoreValues], [[5], [6]]);
o = decoded.VkRenderPassBeginInfo[0];
assert.deepEqual(Array.from(o.pClearValues[0].color.float32).map(v => Math.round(v * 10) / 10), [0.1, 0.2, 0.3, 1]);
assert.deepEqual([o.renderArea.offset.x, o.renderArea.extent.width], [1, 300]);
o = decoded.VkCommandBufferBeginInfo[0];
assert.equal(o.pInheritanceInfo, null);
console.log("PASS: what they decode to");

// Replies: what the guest reads of this encoder's (and writes again) is what was written
for(const name of Object.keys(REPLIES))
{
    assert.equal(reply_hex(name), vectors.reply[name], name + ": the reply as recorded");
    assert.equal(vectors.guest[name], vectors.reply[name], name + ": the guest read the reply as written");
}
console.log("PASS: " + Object.keys(REPLIES).length + " replies, read by the guest's reply readers as written");

// The commands: each decodes and encodes its parameters (the guest's side
// writes them, the device's reads them)
const by_name = {};
for(const [op, entry] of Object.entries(P.COMMANDS)) by_name[entry[0]] = [+op, ...entry.slice(1)];
assert.equal(Object.keys(by_name).length, Object.keys(GUEST_COMMANDS).length);
const roundtrip = (name, a) => {
    const w = new P.GfxWriter(16);
    GUEST_COMMANDS[name][1](w, a);
    const bytes = w.result();
    const r = new P.GfxReader(bytes);
    const back = by_name[name][1](r);
    assert.equal(r.p, bytes.length, name + ": all of it read");
    return back;
};
let a = roundtrip("vkCreateImage", { device: 5, pCreateInfo: decoded.VkImageCreateInfo[0], pAllocator: null, pImage: 0 });
assert.equal(a.device, 5);
assert.equal(a.pCreateInfo.pNext.handle, 77);
a = roundtrip("vkEnumeratePhysicalDevices", { instance: 3, pPhysicalDeviceCount: 1, pPhysicalDevices: [0] });
assert.deepEqual([a.pPhysicalDeviceCount, a.pPhysicalDevices], [1, [0]]);
a = roundtrip("vkEnumerateDeviceExtensionProperties", { physicalDevice: 3, pLayerName: null, pPropertyCount: 2, pProperties: [{}, {}] });
assert.deepEqual([a.pPropertyCount, a.pProperties.length], [2, 2], "an output array of structs: as long as its count");
a = roundtrip("vkCmdDraw", { commandBuffer: 9, vertexCount: 3, instanceCount: 1, firstVertex: 0, firstInstance: 0 });
assert.deepEqual([a.commandBuffer, a.vertexCount], [undefined, 3], "a command buffer's command: no handle (it is the buffer's)");
assert.ok(by_name.vkCmdDraw[3], "vkCmdDraw is in a command buffer's stream");
a = roundtrip("vkQueueFlushCommandsGOOGLE", { queue: 1, commandBuffer: 2, dataSize: 4, pData: Uint8Array.of(1, 2, 3, 4) });
assert.deepEqual(Array.from(a.pData), [1, 2, 3, 4]);
// a reply: the guest reads what the device wrote
const reply = (name, a, request) => {
    const w = new P.GfxWriter(16);
    by_name[name][2](w, a);
    const r = new P.GfxReader(w.result());
    const back = GUEST_COMMANDS[name][2](r, request);
    assert.equal(r.p, w.result().length, name + ": its reply read");
    return back;
};
a = reply("vkEnumeratePhysicalDevices", { pPhysicalDeviceCount: 1, pPhysicalDevices: [0x1000], ret: 0 }, { pPhysicalDeviceCount: 1, pPhysicalDevices: [0] });
assert.deepEqual([a.pPhysicalDeviceCount, a.pPhysicalDevices, a.ret], [1, [0x1000], 0]);
a = reply("vkCreateImageWithRequirementsGOOGLE", { pImage: 0x2000, pMemoryRequirements: { size: 4096, alignment: 256, memoryTypeBits: 1 }, ret: 0 }, {});
assert.deepEqual([a.pImage, a.pMemoryRequirements.size, a.ret], [0x2000, 4096, 0]);
console.log("PASS: commands of both sides");

// A command as Android's ANGLE wrote it (the A9 scenario: SystemUI's
// pipelines, 4 samples): pSampleMask's (rasterizationSamples + 31) / 32
// words, C's division of integers; the rest after it read right
{
    const payload = unhex(fs.readFileSync(__dirname + "/gfxstream_create_graphics_pipelines.hex", "utf8").trim());
    const r = new P.GfxReader(payload, 4);
    const pipelines = by_name.vkCreateGraphicsPipelines[1](r);
    assert.equal(r.p, payload.length, "vkCreateGraphicsPipelines: all of it read");
    const multisample = pipelines.pCreateInfos[0].pMultisampleState;
    assert.equal(multisample.rasterizationSamples, 4);
    assert.equal(multisample.pSampleMask.length, 1, "one word of sample mask");
    console.log("PASS: ANGLE's vkCreateGraphicsPipelines (a sample mask of 4 samples)");
}
